/* Runtime contract of code generated by tools/lift64.py (x86-64 guest -> C).
 *
 * Address model: identity. The guest image is mapped at its real ImageBase
 * (0x140000000 for RDR2) and guest pointers ARE host pointers, so a load is a real
 * dereference of a 64-bit value. This is valid on arm64 Android (39-bit VA) and on the
 * x86-64 host used by the differential test.
 *
 * Flags are materialised eagerly after every flag-setting instruction: simpler than the
 * lazy scheme the 32-bit lifter uses, and easy to diff against the hardware.
 */
#ifndef X64RT_H
#define X64RT_H

#include <stdint.h>
#include <string.h>

#define X64_CF 0x0001u
#define X64_PF 0x0004u
#define X64_AF 0x0010u
#define X64_ZF 0x0040u
#define X64_SF 0x0080u
#define X64_OF 0x0800u
#define X64_DF 0x0400u

typedef struct X64Ctx {
    uint64_t r[16];        /* rax rcx rdx rbx rsp rbp rsi rdi r8..r15 */
    uint64_t xmm[16][2];   /* low/high 64 bits of each XMM register */
    uint64_t flags;        /* subset of EFLAGS: CF PF AF ZF SF OF DF */
    uint64_t rip;          /* guest PC, for diagnostics only */
} X64Ctx;

enum { R_AX = 0, R_CX, R_DX, R_BX, R_SP, R_BP, R_SI, R_DI, R_8, R_9, R_10, R_11, R_12, R_13, R_14, R_15 };

/* ---- flags ------------------------------------------------------------- */
static inline uint64_t x64_szp(uint64_t r, unsigned bits)
{
    uint64_t m = bits == 64 ? ~0ull : ((1ull << bits) - 1);
    uint64_t sign = 1ull << (bits - 1);
    uint64_t f = 0;
    r &= m;
    if (r == 0) f |= X64_ZF;
    if (r & sign) f |= X64_SF;
    if (!__builtin_parityll(r & 0xff)) f |= X64_PF;
    return f;
}

static inline uint64_t x64_add_flags(uint64_t a, uint64_t b, uint64_t r, unsigned bits)
{
    uint64_t m = bits == 64 ? ~0ull : ((1ull << bits) - 1);
    uint64_t sign = 1ull << (bits - 1);
    uint64_t f = x64_szp(r, bits);
    if ((r & m) < (a & m)) f |= X64_CF;
    if (((a ^ r) & (b ^ r)) & sign) f |= X64_OF;
    if (((a ^ b ^ r) & 0x10) != 0) f |= X64_AF;
    return f;
}

static inline uint64_t x64_sub_flags(uint64_t a, uint64_t b, uint64_t r, unsigned bits)
{
    uint64_t m = bits == 64 ? ~0ull : ((1ull << bits) - 1);
    uint64_t sign = 1ull << (bits - 1);
    uint64_t f = x64_szp(r, bits);
    if ((a & m) < (b & m)) f |= X64_CF;
    if (((a ^ b) & (a ^ r)) & sign) f |= X64_OF;
    if (((a ^ b ^ r) & 0x10) != 0) f |= X64_AF;
    return f;
}

static inline uint64_t x64_logic_flags(uint64_t r, unsigned bits)
{
    return x64_szp(r, bits); /* CF = OF = 0 */
}

static inline uint64_t x64_cond(uint64_t flags, int cc)
{
    int cf = !!(flags & X64_CF), zf = !!(flags & X64_ZF), sf = !!(flags & X64_SF),
        of = !!(flags & X64_OF), pf = !!(flags & X64_PF);
    switch (cc) {
    case 0: return of;                        /* o  */
    case 1: return !of;                       /* no */
    case 2: return cf;                        /* b  */
    case 3: return !cf;                       /* ae */
    case 4: return zf;                        /* e  */
    case 5: return !zf;                       /* ne */
    case 6: return cf || zf;                  /* be */
    case 7: return !cf && !zf;                /* a  */
    case 8: return sf;                        /* s  */
    case 9: return !sf;                       /* ns */
    case 10: return pf;                       /* p  */
    case 11: return !pf;                      /* np */
    case 12: return sf != of;                 /* l  */
    case 13: return sf == of;                 /* ge */
    case 14: return zf || (sf != of);         /* le */
    case 15: return !zf && (sf == of);        /* g  */
    default: return 0;
    }
}

/* ---- memory (identity mapping) ----------------------------------------- */
#define X64_LD8(a)  (*(const uint8_t  *)(uintptr_t)(a))
#define X64_LD16(a) (*(const uint16_t *)(uintptr_t)(a))
#define X64_LD32(a) (*(const uint32_t *)(uintptr_t)(a))
#define X64_LD64(a) (*(const uint64_t *)(uintptr_t)(a))
#define X64_ST8(a, v)  (*(uint8_t  *)(uintptr_t)(a) = (uint8_t)(v))
#define X64_ST16(a, v) (*(uint16_t *)(uintptr_t)(a) = (uint16_t)(v))
#define X64_ST32(a, v) (*(uint32_t *)(uintptr_t)(a) = (uint32_t)(v))
#define X64_ST64(a, v) (*(uint64_t *)(uintptr_t)(a) = (uint64_t)(v))

/* Vector views of the XMM registers. On arm64 these are NEON types; on the x86-64 test
 * host they are SSE. Lane layout matches x86. */
typedef float    v4f __attribute__((vector_size(16)));
typedef uint32_t v4u __attribute__((vector_size(16)));
typedef int32_t  v4i __attribute__((vector_size(16)));
typedef double   v2d __attribute__((vector_size(16)));

typedef void (*X64Fn)(X64Ctx *);

#endif /* X64RT_H */
